package git

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// GitRepoConfig represents a git repository configuration
type GitRepoConfig struct {
	ID      string `json:"id"`
	URL     string `json:"url"`
	Name    string `json:"name"`
	Enabled bool   `json:"enabled"`
}

// ConfigManager manages git repository configurations
type ConfigManager struct {
	configPath string
}

// NewConfigManager creates a new ConfigManager
func NewConfigManager(skillsDir string) *ConfigManager {
	return &ConfigManager{
		configPath: filepath.Join(skillsDir, ".git-repos.json"),
	}
}

// LoadConfig loads git repository configurations from the config file
func (cm *ConfigManager) LoadConfig() ([]GitRepoConfig, error) {
	// If config file doesn't exist, return empty slice
	if _, err := os.Stat(cm.configPath); os.IsNotExist(err) {
		return []GitRepoConfig{}, nil
	}

	data, err := os.ReadFile(cm.configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file: %w", err)
	}

	var repos []GitRepoConfig
	if len(data) == 0 {
		return []GitRepoConfig{}, nil
	}

	if err := json.Unmarshal(data, &repos); err != nil {
		return nil, fmt.Errorf("failed to parse config file: %w", err)
	}

	return repos, nil
}

// SaveConfig saves git repository configurations to the config file
func (cm *ConfigManager) SaveConfig(repos []GitRepoConfig) error {
	// Ensure directory exists
	dir := filepath.Dir(cm.configPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create config directory: %w", err)
	}

	data, err := json.MarshalIndent(repos, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal config: %w", err)
	}

	if err := os.WriteFile(cm.configPath, data, 0644); err != nil {
		return fmt.Errorf("failed to write config file: %w", err)
	}

	return nil
}

// ExtractRepoName extracts a repository name from a URL
func ExtractRepoName(repoURL string) string {
	// Remove protocol and .git suffix
	name := strings.TrimSuffix(repoURL, ".git")

	// Extract last part of path
	parts := strings.Split(name, "/")
	if len(parts) > 0 {
		name = parts[len(parts)-1]
	}

	// Remove protocol prefix if present
	if strings.Contains(name, "://") {
		parts = strings.Split(name, "://")
		if len(parts) > 1 {
			parts = strings.Split(parts[1], "/")
			if len(parts) > 0 {
				name = parts[len(parts)-1]
			}
		}
	}

	return name
}

// GenerateID generates a unique ID for a git repo config
func GenerateID(repoURL string) string {
	// Use a simple hash-like approach: take first 8 chars of URL hash
	// In a real implementation, you might want to use a proper hash function
	name := ExtractRepoName(repoURL)
	return strings.ToLower(strings.ReplaceAll(name, "-", ""))
}

package domain

import (
	"fmt"
	"mime"
	"path/filepath"
	"strings"
	"time"
)

// ResourceType represents the type of resource directory
type ResourceType string

const (
	ResourceTypeScript    ResourceType = "script"
	ResourceTypeReference ResourceType = "reference"
	ResourceTypeAsset     ResourceType = "asset"
)

// SkillResource represents a resource file in a skill
type SkillResource struct {
	Type     ResourceType
	Path     string    // Relative path from skill root (e.g., "scripts/script.py")
	Name     string    // Filename only
	Size     int64     // File size in bytes
	MimeType string    // MIME type
	Readable bool      // true if text file, false if binary
	Modified time.Time // Last modification time
}

// ResourceContent represents the content of a resource
type ResourceContent struct {
	Content  string // UTF-8 for text, base64 for binary
	Encoding string // "utf-8" or "base64"
	MimeType string
	Size     int64
}

// ValidateResourcePath validates a resource path
func ValidateResourcePath(path string) error {
	// Normalize path separators
	path = filepath.ToSlash(path)

	// Must start with one of the resource directory names
	validPrefixes := []string{"scripts/", "references/", "assets/"}
	valid := false
	for _, prefix := range validPrefixes {
		if strings.HasPrefix(path, prefix) {
			valid = true
			break
		}
	}
	if !valid {
		return fmt.Errorf("resource path must start with scripts/, references/, or assets/")
	}

	// Check for path traversal
	if strings.Contains(path, "..") {
		return fmt.Errorf("resource path cannot contain '..'")
	}

	// Check for absolute paths
	if filepath.IsAbs(path) {
		return fmt.Errorf("resource path must be relative")
	}

	return nil
}

// GetResourceType determines the resource type from a path
func GetResourceType(path string) ResourceType {
	path = filepath.ToSlash(path)
	if strings.HasPrefix(path, "scripts/") {
		return ResourceTypeScript
	}
	if strings.HasPrefix(path, "references/") {
		return ResourceTypeReference
	}
	if strings.HasPrefix(path, "assets/") {
		return ResourceTypeAsset
	}
	return ResourceTypeAsset // Default fallback
}

// IsTextFile determines if a file is text-based based on MIME type
func IsTextFile(mimeType string) bool {
	if strings.HasPrefix(mimeType, "text/") {
		return true
	}
	// Common text-based MIME types
	textMimeTypes := []string{
		"application/json",
		"application/xml",
		"application/javascript",
		"application/x-sh",
		"application/x-python",
		"application/x-yaml",
		"application/x-toml",
	}
	for _, t := range textMimeTypes {
		if mimeType == t {
			return true
		}
	}
	return false
}

// DetectMimeType detects MIME type from file extension and content
func DetectMimeType(filename string, content []byte) string {
	ext := filepath.Ext(filename)
	mimeType := mime.TypeByExtension(ext)
	if mimeType == "" {
		// Try to detect from content
		if len(content) > 0 {
			// Check for text file signatures
			if isTextContent(content) {
				// Default to text/plain for unknown text files
				return "text/plain"
			}
		}
		return "application/octet-stream"
	}
	return mimeType
}

// isTextContent checks if content appears to be text
func isTextContent(content []byte) bool {
	// Check first 512 bytes for null bytes
	checkLen := len(content)
	if checkLen > 512 {
		checkLen = 512
	}
	for i := 0; i < checkLen; i++ {
		if content[i] == 0 {
			return false
		}
	}
	return true
}

package web

import (
	"context"
	"embed"
	"io"
	"io/fs"
	"log/slog"
	"net/http"
	"time"

	"github.com/labstack/echo/v5"
	"github.com/labstack/echo/v5/middleware"

	"github.com/mudler/skillserver/pkg/domain"
	"github.com/mudler/skillserver/pkg/git"
)

//go:embed ui
var uiFiles embed.FS

// Server wraps the Echo server
type Server struct {
	echo          *echo.Echo
	httpServer    *http.Server
	skillManager  domain.SkillManager
	fsManager     *domain.FileSystemManager
	gitRepos      []string
	gitSyncer     *git.GitSyncer
	configManager *git.ConfigManager
}

// NewServer creates a new web server
func NewServer(skillManager domain.SkillManager, fsManager *domain.FileSystemManager, gitRepos []string, gitSyncer *git.GitSyncer, configManager *git.ConfigManager, enableLogging bool) *Server {
	e := echo.New()

	// Middleware
	// Only enable request logging if explicitly enabled (to avoid interfering with MCP stdio)
	if enableLogging {
		e.Use(middleware.RequestLogger())
	} else {
		e.Logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	e.Use(middleware.Recover())
	//e.Use(middleware.CORS())

	server := &Server{
		echo:          e,
		skillManager:  skillManager,
		fsManager:     fsManager,
		gitRepos:      gitRepos,
		gitSyncer:     gitSyncer,
		configManager: configManager,
	}

	// API routes
	api := e.Group("/api")
	api.GET("/skills", server.listSkills)
	api.GET("/skills/:name", server.getSkill)
	api.POST("/skills", server.createSkill)
	api.PUT("/skills/:name", server.updateSkill)
	api.DELETE("/skills/:name", server.deleteSkill)
	api.GET("/skills/search", server.searchSkills)

	// Import/Export routes
	// Use wildcard for export to handle skill names with slashes (repoName/skillName)
	// Register before other /skills routes to ensure it matches first
	api.GET("/skills/export/*", server.exportSkill)
	api.POST("/skills/import", server.importSkill)

	// Resource management routes
	api.GET("/skills/:name/resources", server.listSkillResources)
	api.GET("/skills/:name/resources/*", server.getSkillResource)
	api.POST("/skills/:name/resources", server.createSkillResource)
	api.PUT("/skills/:name/resources/*", server.updateSkillResource)
	api.DELETE("/skills/:name/resources/*", server.deleteSkillResource)

	// Git repository management routes
	api.GET("/git-repos", server.listGitRepos)
	api.POST("/git-repos", server.addGitRepo)
	api.PUT("/git-repos/:id", server.updateGitRepo)
	api.DELETE("/git-repos/:id", server.deleteGitRepo)
	api.POST("/git-repos/:id/sync", server.syncGitRepo)
	api.POST("/git-repos/:id/toggle", server.toggleGitRepo)

	// Serve UI
	uiFS, err := fs.Sub(uiFiles, "ui")
	if err != nil {
		panic(err)
	}
	e.GET("/*", echo.WrapHandler(http.FileServer(http.FS(uiFS))))

	return server
}

// Start starts the web server
func (s *Server) Start(addr string) error {
	s.httpServer = &http.Server{
		Addr:    addr,
		Handler: s.echo,
	}
	return s.httpServer.ListenAndServe()
}

// Shutdown gracefully shuts down the server
func (s *Server) Shutdown() error {
	if s.httpServer == nil {
		return nil
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return s.httpServer.Shutdown(ctx)
}

package main

import (
	"context"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"

	"github.com/mudler/skillserver/pkg/domain"
	"github.com/mudler/skillserver/pkg/git"
	"github.com/mudler/skillserver/pkg/mcp"
	"github.com/mudler/skillserver/pkg/web"
)

// getEnvOrDefault returns the environment variable value or a default value
func getEnvOrDefault(key, defaultValue string) string {
	if value := os.Getenv(key); value != "" {
		return value
	}
	return defaultValue
}

// getEnvOrEmpty returns the environment variable value or empty string
func getEnvOrEmpty(key string) string {
	return os.Getenv(key)
}

// getEnvBool returns the environment variable as a boolean, or default value
func getEnvBool(key string, defaultValue bool) bool {
	if value := os.Getenv(key); value != "" {
		if parsed, err := strconv.ParseBool(value); err == nil {
			return parsed
		}
	}
	return defaultValue
}

// setupLogger configures logging based on the enable flag
// When disabled, all logs go to io.Discard to avoid interfering with stdio MCP protocol
func setupLogger(enable bool) *log.Logger {
	var writer io.Writer
	if enable {
		writer = os.Stderr // Use stderr for logs when enabled (doesn't interfere with MCP stdio)
	} else {
		writer = io.Discard // Discard all logs when disabled
	}
	return log.New(writer, "", log.LstdFlags)
}

// extractRepoName extracts a repository name from a URL (same logic as GitSyncer)
func extractRepoName(repoURL string) string {
	// Remove protocol and .git suffix
	name := strings.TrimSuffix(repoURL, ".git")

	// Extract last part of path
	parts := strings.Split(name, "/")
	if len(parts) > 0 {
		name = parts[len(parts)-1]
	}

	// Remove protocol prefix if present
	if strings.Contains(name, "://") {
		parts = strings.Split(name, "://")
		if len(parts) > 1 {
			parts = strings.Split(parts[1], "/")
			if len(parts) > 0 {
				name = parts[len(parts)-1]
			}
		}
	}

	return name
}

func main() {
	// Get default values from environment variables
	defaultDir := getEnvOrDefault("SKILLSERVER_DIR", getEnvOrDefault("SKILLS_DIR", "./skills"))
	defaultPort := getEnvOrDefault("SKILLSERVER_PORT", getEnvOrDefault("PORT", "8080"))
	defaultGitRepos := getEnvOrEmpty("SKILLSERVER_GIT_REPOS")
	if defaultGitRepos == "" {
		defaultGitRepos = getEnvOrEmpty("GIT_REPOS")
	}
	// Logging defaults to false (disabled) to avoid interfering with MCP stdio
	defaultEnableLogging := getEnvBool("SKILLSERVER_ENABLE_LOGGING", false)

	// Parse command line flags (flags override environment variables)
	skillsDir := flag.String("dir", defaultDir, "Directory to store skills (env: SKILLSERVER_DIR or SKILLS_DIR)")
	port := flag.String("port", defaultPort, "Port for the web server (env: SKILLSERVER_PORT or PORT)")
	gitReposFlag := flag.String("git-repos", defaultGitRepos, "Comma-separated list of Git repository URLs to sync (env: SKILLSERVER_GIT_REPOS or GIT_REPOS)")
	enableLogging := flag.Bool("enable-logging", defaultEnableLogging, "Enable logging to stderr (env: SKILLSERVER_ENABLE_LOGGING). Default: false (disabled to avoid interfering with MCP stdio)")
	flag.Parse()

	// Setup logger based on flag
	logger := setupLogger(*enableLogging)
	log.SetOutput(logger.Writer())
	log.SetFlags(logger.Flags())

	// Get final values (flags take precedence over env vars)
	finalDir := *skillsDir
	finalPort := *port
	finalGitRepos := *gitReposFlag

	// Initialize config manager
	configManager := git.NewConfigManager(finalDir)

	// Load git repos from config file or use command line/env repos
	var gitRepos []string
	configRepos, err := configManager.LoadConfig()
	if err != nil && *enableLogging {
		log.Printf("Warning: Failed to load git repo config: %v", err)
	}

	// If config file has repos, use them; otherwise use command line/env repos
	if len(configRepos) > 0 {
		for _, repo := range configRepos {
			if repo.Enabled {
				gitRepos = append(gitRepos, repo.URL)
			}
		}
	} else {
		// Parse git repos from command line/env
		if finalGitRepos != "" {
			parsedRepos := strings.Split(finalGitRepos, ",")
			for i := range parsedRepos {
				parsedRepos[i] = strings.TrimSpace(parsedRepos[i])
			}
			gitRepos = parsedRepos

			// Save to config file if we have repos from command line/env
			if len(gitRepos) > 0 {
				configs := make([]git.GitRepoConfig, len(gitRepos))
				for i, url := range gitRepos {
					configs[i] = git.GitRepoConfig{
						ID:      git.GenerateID(url),
						URL:     url,
						Name:    git.ExtractRepoName(url),
						Enabled: true,
					}
				}
				if err := configManager.SaveConfig(configs); err != nil && *enableLogging {
					log.Printf("Warning: Failed to save git repo config: %v", err)
				}
			}
		}
	}

	// Extract git repo names from URLs for read-only detection
	var gitRepoNames []string
	for _, repoURL := range gitRepos {
		repoName := git.ExtractRepoName(repoURL)
		if repoName != "" {
			gitRepoNames = append(gitRepoNames, repoName)
		}
	}

	// Initialize skill manager
	skillManager, err := domain.NewFileSystemManager(finalDir, gitRepoNames)
	if err != nil {
		log.Fatalf("Failed to initialize skill manager: %v", err)
	}

	// Get FileSystemManager reference for handlers
	fsManager := skillManager

	// Initialize Git syncer if repos are provided
	var gitSyncer *git.GitSyncer
	gitSyncer = git.NewGitSyncer(finalDir, gitRepos, func() error {
		return skillManager.RebuildIndex()
	})
	// Configure git syncer output based on logging flag
	if *enableLogging {
		gitSyncer.SetProgressWriter(os.Stderr) // Use stderr for git progress
		gitSyncer.SetLogger(os.Stderr)         // Use stderr for log messages
	}
	if err := gitSyncer.Start(); err != nil {
		log.Printf("Warning: Failed to start Git syncer: %v", err)
	} else if *enableLogging {
		log.Println("Git syncer started")
	}

	// Create context for graceful shutdown
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Setup signal handling
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)

	// Start web server in a goroutine (non-blocking)
	webServer := web.NewServer(skillManager, fsManager, gitRepos, gitSyncer, configManager, *enableLogging)
	go func() {
		addr := fmt.Sprintf(":%s", finalPort)
		if *enableLogging {
			log.Printf("Starting web server on %s", addr)
		}
		if err := webServer.Start(addr); err != nil {
			log.Printf("Web server error: %v", err)
		}
	}()

	// Start MCP server on main thread (blocking, stdio)
	mcpServer := mcp.NewServer(skillManager)

	// Handle shutdown in a goroutine
	go func() {
		<-sigChan
		if *enableLogging {
			log.Println("Shutting down...")
		}

		// Stop Git syncer
		if gitSyncer != nil {
			gitSyncer.Stop()
		}

		// Shutdown web server
		if err := webServer.Shutdown(); err != nil {
			log.Printf("Error shutting down web server: %v", err)
		}

		cancel()
		if *enableLogging {
			log.Println("Shutdown complete")
		}
	}()

	// Run MCP server (blocks main thread)
	// Note: No logging here to avoid interfering with stdio protocol
	if err := mcpServer.Run(ctx); err != nil {
		// Only log errors if logging is enabled
		if *enableLogging {
			log.Printf("MCP server error: %v", err)
		}
	}
}

package domain

import (
	"fmt"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

// FlexibleStringList is a type that can unmarshal from either a YAML string
// (space-delimited) or a YAML list of strings, storing the result as a
// space-delimited string for backward compatibility.
type FlexibleStringList string

func (f FlexibleStringList) String() string {
	return string(f)
}

// UnmarshalYAML implements custom YAML unmarshaling for FlexibleStringList
func (f *FlexibleStringList) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		// Plain string: "Bash Read Write"
		*f = FlexibleStringList(value.Value)
		return nil
	case yaml.SequenceNode:
		// List: ["Bash", "Read", "Write"]
		var items []string
		for _, item := range value.Content {
			if item.Kind == yaml.ScalarNode {
				items = append(items, item.Value)
			}
		}
		*f = FlexibleStringList(strings.Join(items, " "))
		return nil
	default:
		return fmt.Errorf("allowed-tools must be a string or list of strings")
	}
}

// SkillMetadata represents YAML frontmatter metadata per Agent Skills specification
type SkillMetadata struct {
	Name          string             `yaml:"name"`        // Required, 1-64 chars, lowercase alphanumeric + hyphens
	Description   string             `yaml:"description"` // Required
	License       string             `yaml:"license,omitempty"`
	Compatibility string             `yaml:"compatibility,omitempty"` // Max 500 chars
	Metadata      map[string]string  `yaml:"metadata,omitempty"`
	AllowedTools  FlexibleStringList `yaml:"allowed-tools,omitempty"` // Space-delimited string or YAML list
}

// Skill represents a skill directory with SKILL.md file
type Skill struct {
	Name       string // Display name (same as ID for local skills, repoName/skillName for git repo skills)
	ID         string // Unique identifier to use when reading the skill (repoName/skillName or skillName)
	Content    string
	Metadata   *SkillMetadata
	SourcePath string // Full path to the skill directory
	ReadOnly   bool   // True if skill is from a git repository
}

var (
	// Valid skill name pattern: lowercase letters, numbers, hyphens, 1-64 chars, no leading/trailing hyphens, no consecutive hyphens
	skillNamePattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]*[a-z0-9])?$`)
)

// ValidateSkillName validates a skill name according to Agent Skills specification
func ValidateSkillName(name string) error {
	if len(name) == 0 {
		return fmt.Errorf("skill name is required")
	}
	if len(name) > 64 {
		return fmt.Errorf("skill name must be 1-64 characters, got %d", len(name))
	}
	if strings.HasPrefix(name, "-") || strings.HasSuffix(name, "-") {
		return fmt.Errorf("skill name cannot start or end with a hyphen")
	}
	if strings.Contains(name, "--") {
		return fmt.Errorf("skill name cannot contain consecutive hyphens")
	}
	if !skillNamePattern.MatchString(name) {
		return fmt.Errorf("skill name may only contain lowercase letters, numbers, and hyphens")
	}
	return nil
}

// ParseFrontmatter extracts YAML frontmatter from markdown content
// Returns the metadata (if present) and the remaining content
func ParseFrontmatter(content string) (*SkillMetadata, string, error) {
	content = strings.TrimSpace(content)
	if !strings.HasPrefix(content, "---") {
		return nil, content, fmt.Errorf("frontmatter is required (must start with ---)")
	}

	// Find the end of frontmatter
	endIdx := strings.Index(content[3:], "---")
	if endIdx == -1 {
		return nil, content, fmt.Errorf("malformed frontmatter (missing closing ---)")
	}

	frontmatter := content[3 : endIdx+3]
	remaining := strings.TrimSpace(content[endIdx+6:])

	// First try strict parsing into SkillMetadata
	var metadata SkillMetadata
	if err := yaml.Unmarshal([]byte(frontmatter), &metadata); err != nil {
		// If strict parsing fails, try a lenient approach:
		// parse only the known fields we need (name, description) from a generic map
		var raw map[string]interface{}
		if yamlErr := yaml.Unmarshal([]byte(frontmatter), &raw); yamlErr != nil {
			return nil, content, fmt.Errorf("failed to parse frontmatter: %w", yamlErr)
		}
		if name, ok := raw["name"].(string); ok {
			metadata.Name = name
		}
		if desc, ok := raw["description"].(string); ok {
			metadata.Description = desc
		}
		if license, ok := raw["license"].(string); ok {
			metadata.License = license
		}
		if compat, ok := raw["compatibility"].(string); ok {
			metadata.Compatibility = compat
		}
		// allowed-tools handled best-effort: skip if format is unrecognized
	}

	// Validate required fields
	if metadata.Name == "" {
		return nil, content, fmt.Errorf("frontmatter 'name' field is required")
	}
	if err := ValidateSkillName(metadata.Name); err != nil {
		return nil, content, fmt.Errorf("invalid skill name: %w", err)
	}
	if metadata.Description == "" {
		return nil, content, fmt.Errorf("frontmatter 'description' field is required")
	}

	return &metadata, remaining, nil
}

package git

import (
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing/transport"
)

// GitSyncer handles synchronization with Git repositories
type GitSyncer struct {
	skillsDir string
	repos     []string
	mu        sync.RWMutex // Mutex for thread-safe repo access
	ctx       context.Context
	cancel    context.CancelFunc
	onUpdate  func() error // Callback to trigger re-indexing
	progress  io.Writer    // Writer for git progress output (nil = disabled)
	logger    io.Writer    // Writer for log messages (nil = disabled)
}

// NewGitSyncer creates a new GitSyncer
func NewGitSyncer(skillsDir string, repos []string, onUpdate func() error) *GitSyncer {
	ctx, cancel := context.WithCancel(context.Background())
	return &GitSyncer{
		skillsDir: skillsDir,
		repos:     repos,
		ctx:       ctx,
		cancel:    cancel,
		onUpdate:  onUpdate,
		progress:  nil, // Default to no progress output (to avoid interfering with MCP stdio)
		logger:    nil, // Default to no logging
	}
}

// SetProgressWriter sets the writer for git progress output
func (g *GitSyncer) SetProgressWriter(w io.Writer) {
	g.progress = w
}

// SetLogger sets the writer for log messages
func (g *GitSyncer) SetLogger(w io.Writer) {
	g.logger = w
}

// Start begins the Git synchronization process
func (g *GitSyncer) Start() error {
	// Initial sync
	if err := g.syncAll(); err != nil {
		return fmt.Errorf("initial sync failed: %w", err)
	}

	// Start periodic sync in background
	go g.periodicSync()

	return nil
}

// Stop stops the Git synchronization
func (g *GitSyncer) Stop() {
	g.cancel()
}

// GetRepos returns a copy of the current repository list
func (g *GitSyncer) GetRepos() []string {
	g.mu.RLock()
	defer g.mu.RUnlock()
	repos := make([]string, len(g.repos))
	copy(repos, g.repos)
	return repos
}

// AddRepo adds a new repository and syncs it
func (g *GitSyncer) AddRepo(repoURL string) error {
	g.mu.Lock()
	// Check if repo already exists
	for _, existing := range g.repos {
		if existing == repoURL {
			g.mu.Unlock()
			return fmt.Errorf("repository already exists: %s", repoURL)
		}
	}
	g.repos = append(g.repos, repoURL)
	g.mu.Unlock()

	// Sync the new repo
	if err := g.syncRepo(repoURL); err != nil {
		// Remove from list if sync failed
		g.mu.Lock()
		for i, r := range g.repos {
			if r == repoURL {
				g.repos = append(g.repos[:i], g.repos[i+1:]...)
				break
			}
		}
		g.mu.Unlock()
		return fmt.Errorf("failed to sync new repository: %w", err)
	}

	// Trigger re-indexing
	if g.onUpdate != nil {
		if err := g.onUpdate(); err != nil {
			return fmt.Errorf("failed to trigger re-indexing: %w", err)
		}
	}

	return nil
}

// RemoveRepo removes a repository from the list
func (g *GitSyncer) RemoveRepo(repoURL string) error {
	g.mu.Lock()
	defer g.mu.Unlock()

	found := false
	for i, r := range g.repos {
		if r == repoURL {
			g.repos = append(g.repos[:i], g.repos[i+1:]...)
			found = true
			break
		}
	}

	if !found {
		return fmt.Errorf("repository not found: %s", repoURL)
	}

	return nil
}

// GetSkillsDir returns the skills directory path
func (g *GitSyncer) GetSkillsDir() string {
	return g.skillsDir
}

// UpdateRepos updates the repository list with new URLs
func (g *GitSyncer) UpdateRepos(repos []string) error {
	g.mu.Lock()
	oldRepos := make([]string, len(g.repos))
	copy(oldRepos, g.repos)
	g.repos = repos
	g.mu.Unlock()

	// Sync all repos
	if err := g.syncAll(); err != nil {
		// Restore old repos on error
		g.mu.Lock()
		g.repos = oldRepos
		g.mu.Unlock()
		return err
	}

	return nil
}

// syncAll syncs all configured repositories
func (g *GitSyncer) syncAll() error {
	repos := g.GetRepos()
	for _, repoURL := range repos {
		if err := g.syncRepo(repoURL); err != nil {
			// Log error but continue with other repos (only if logger is set)
			if g.logger != nil {
				fmt.Fprintf(g.logger, "Warning: failed to sync repo %s: %v\n", repoURL, err)
			}
		}
	}

	// Trigger re-indexing if callback is set
	if g.onUpdate != nil {
		if err := g.onUpdate(); err != nil {
			return fmt.Errorf("failed to trigger re-indexing: %w", err)
		}
	}

	return nil
}

// syncRepo syncs a single repository
func (g *GitSyncer) syncRepo(repoURL string) error {
	// Extract repo name from URL
	repoName := g.extractRepoName(repoURL)
	targetDir := filepath.Join(g.skillsDir, repoName)

	// Check if directory exists
	_, err := os.Stat(targetDir)
	if os.IsNotExist(err) {
		// Clone the repository
		return g.cloneRepo(repoURL, targetDir)
	} else if err != nil {
		return fmt.Errorf("failed to check directory: %w", err)
	}

	// Pull updates
	return g.pullRepo(targetDir)
}

// cloneRepo clones a repository
func (g *GitSyncer) cloneRepo(repoURL, targetDir string) error {
	_, err := git.PlainClone(targetDir, false, &git.CloneOptions{
		URL:      repoURL,
		Progress: g.progress, // Use progress writer (nil = no output)
	})
	if err != nil {
		// Handle authentication errors gracefully
		if err == transport.ErrAuthenticationRequired {
			return fmt.Errorf("authentication required for %s", repoURL)
		}
		return fmt.Errorf("failed to clone repository: %w", err)
	}
	return nil
}

// pullRepo pulls updates from a repository
func (g *GitSyncer) pullRepo(repoDir string) error {
	r, err := git.PlainOpen(repoDir)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	w, err := r.Worktree()
	if err != nil {
		return fmt.Errorf("failed to get worktree: %w", err)
	}

	err = w.Pull(&git.PullOptions{
		Progress: g.progress, // Use progress writer (nil = no output)
	})
	if err != nil {
		if err == git.NoErrAlreadyUpToDate {
			// Not an error, just already up to date
			return nil
		}
		if err == transport.ErrAuthenticationRequired {
			return fmt.Errorf("authentication required")
		}
		return fmt.Errorf("failed to pull: %w", err)
	}

	return nil
}

// SyncRepo manually syncs a specific repository by URL
func (g *GitSyncer) SyncRepo(repoURL string) error {
	// Check if repo is in the list
	repos := g.GetRepos()
	found := false
	for _, r := range repos {
		if r == repoURL {
			found = true
			break
		}
	}
	if !found {
		return fmt.Errorf("repository not configured: %s", repoURL)
	}

	if err := g.syncRepo(repoURL); err != nil {
		return err
	}

	// Trigger re-indexing
	if g.onUpdate != nil {
		if err := g.onUpdate(); err != nil {
			return fmt.Errorf("failed to trigger re-indexing: %w", err)
		}
	}

	return nil
}

// extractRepoName extracts a repository name from a URL
func (g *GitSyncer) extractRepoName(repoURL string) string {
	// Remove protocol and .git suffix
	name := strings.TrimSuffix(repoURL, ".git")

	// Extract last part of path
	parts := strings.Split(name, "/")
	if len(parts) > 0 {
		name = parts[len(parts)-1]
	}

	// Remove protocol prefix if present
	if strings.Contains(name, "://") {
		parts = strings.Split(name, "://")
		if len(parts) > 1 {
			parts = strings.Split(parts[1], "/")
			if len(parts) > 0 {
				name = parts[len(parts)-1]
			}
		}
	}

	return name
}

// periodicSync runs periodic synchronization every 5 minutes
func (g *GitSyncer) periodicSync() {
	ticker := time.NewTicker(5 * time.Minute)
	defer ticker.Stop()

	for {
		select {
		case <-g.ctx.Done():
			return
		case <-ticker.C:
			if err := g.syncAll(); err != nil {
				fmt.Printf("Warning: periodic sync failed: %v\n", err)
			}
		}
	}
}

package domain

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// ExportSkill creates a tar.gz archive containing the skill directory
// Returns the archive data as bytes
func ExportSkill(skillID string, skillsDir string) ([]byte, error) {
	// Get the skill path
	var skillPath string
	if strings.Contains(skillID, "/") {
		// Git repo skill
		parts := strings.Split(skillID, "/")
		if len(parts) == 2 {
			repoName := parts[0]
			skillDirName := parts[1]
			repoPath := filepath.Join(skillsDir, repoName)

			// Find skill directory within repo
			var err error
			skillPath, err = findSkillDirByName(repoPath, skillDirName)
			if err != nil {
				return nil, fmt.Errorf("skill not found: %s", skillID)
			}
		} else {
			return nil, fmt.Errorf("invalid skill ID format: %s", skillID)
		}
	} else {
		// Local skill
		skillPath = filepath.Join(skillsDir, skillID)
		skillMdPath := filepath.Join(skillPath, "SKILL.md")
		if _, err := os.Stat(skillMdPath); err != nil {
			return nil, fmt.Errorf("skill not found: %s", skillID)
		}
	}

	// Get skill name (directory name)
	skillName := filepath.Base(skillPath)

	// Create a buffer to write the archive
	var buf bytes.Buffer
	gzw := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gzw)

	// Walk the skill directory and add files to archive
	err := filepath.Walk(skillPath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		// Skip the directory itself, but include its contents
		if path == skillPath {
			return nil
		}

		// Get relative path from skill directory
		relPath, err := filepath.Rel(skillPath, path)
		if err != nil {
			return err
		}

		// Create archive path: skill-name/relative-path
		archivePath := filepath.Join(skillName, relPath)
		// Normalize path separators for tar format
		archivePath = filepath.ToSlash(archivePath)

		// Create tar header
		header, err := tar.FileInfoHeader(info, "")
		if err != nil {
			return err
		}
		header.Name = archivePath

		// Write header
		if err := tw.WriteHeader(header); err != nil {
			return err
		}

		// If it's a directory, we're done
		if info.IsDir() {
			return nil
		}

		// Write file content
		file, err := os.Open(path)
		if err != nil {
			return err
		}
		defer file.Close()

		_, err = io.Copy(tw, file)
		return err
	})

	if err != nil {
		tw.Close()
		gzw.Close()
		return nil, fmt.Errorf("failed to create archive: %w", err)
	}

	// Close tar writer
	if err := tw.Close(); err != nil {
		gzw.Close()
		return nil, fmt.Errorf("failed to close tar writer: %w", err)
	}

	// Close gzip writer
	if err := gzw.Close(); err != nil {
		return nil, fmt.Errorf("failed to close gzip writer: %w", err)
	}

	return buf.Bytes(), nil
}

// ImportSkill extracts a tar.gz archive and imports the skill
// Returns the skill name if successful
func ImportSkill(archiveData []byte, skillsDir string) (string, error) {
	// Create a reader from the archive data
	r := bytes.NewReader(archiveData)
	gzr, err := gzip.NewReader(r)
	if err != nil {
		return "", fmt.Errorf("failed to create gzip reader: %w", err)
	}
	defer gzr.Close()

	tarReader := tar.NewReader(gzr)

	var skillName string
	var skillDir string
	var hasSkillMd bool

	// First pass: validate archive structure and find skill name
	for {
		header, err := tarReader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return "", fmt.Errorf("failed to read tar header: %w", err)
		}

		// Extract skill name from first entry
		if skillName == "" {
			parts := strings.Split(header.Name, "/")
			if len(parts) > 0 {
				skillName = parts[0]
				// Validate skill name
				if err := ValidateSkillName(skillName); err != nil {
					return "", fmt.Errorf("invalid skill name in archive: %w", err)
				}
				skillDir = filepath.Join(skillsDir, skillName)
			}
		}

		// Check for SKILL.md
		if strings.HasSuffix(header.Name, "SKILL.md") {
			hasSkillMd = true
		}

		// Validate path to prevent directory traversal
		if strings.Contains(header.Name, "..") {
			return "", fmt.Errorf("invalid path in archive: %s", header.Name)
		}
	}

	if skillName == "" {
		return "", fmt.Errorf("archive does not contain a skill directory")
	}

	if !hasSkillMd {
		return "", fmt.Errorf("archive does not contain SKILL.md file")
	}

	// Check if skill already exists
	existingSkillPath := filepath.Join(skillsDir, skillName)
	if _, err := os.Stat(existingSkillPath); err == nil {
		return "", fmt.Errorf("skill '%s' already exists", skillName)
	}

	// Reset reader for second pass
	r = bytes.NewReader(archiveData)
	gzr, err = gzip.NewReader(r)
	if err != nil {
		return "", fmt.Errorf("failed to create gzip reader: %w", err)
	}
	defer gzr.Close()

	tarReader = tar.NewReader(gzr)

	// Second pass: extract files
	for {
		header, err := tarReader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return "", fmt.Errorf("failed to read tar header: %w", err)
		}

		// Get relative path from skill name
		parts := strings.Split(header.Name, "/")
		if len(parts) < 2 {
			continue // Skip root directory entry
		}
		relPath := strings.Join(parts[1:], string(filepath.Separator))
		targetPath := filepath.Join(skillsDir, skillName, relPath)

		// Validate path to prevent directory traversal
		if strings.Contains(relPath, "..") {
			return "", fmt.Errorf("invalid path in archive: %s", header.Name)
		}

		// Ensure target is within skills directory
		absTarget, err := filepath.Abs(targetPath)
		if err != nil {
			return "", fmt.Errorf("failed to get absolute path: %w", err)
		}
		absSkillsDir, err := filepath.Abs(skillsDir)
		if err != nil {
			return "", fmt.Errorf("failed to get absolute skills dir: %w", err)
		}
		if !strings.HasPrefix(absTarget, absSkillsDir) {
			return "", fmt.Errorf("invalid path: outside skills directory")
		}

		switch header.Typeflag {
		case tar.TypeDir:
			// Create directory
			if err := os.MkdirAll(targetPath, os.FileMode(header.Mode)); err != nil {
				return "", fmt.Errorf("failed to create directory: %w", err)
			}
		case tar.TypeReg:
			// Create parent directories
			if err := os.MkdirAll(filepath.Dir(targetPath), 0755); err != nil {
				return "", fmt.Errorf("failed to create parent directory: %w", err)
			}

			// Create file
			outFile, err := os.OpenFile(targetPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, os.FileMode(header.Mode))
			if err != nil {
				return "", fmt.Errorf("failed to create file: %w", err)
			}

			// Copy file content
			if _, err := io.Copy(outFile, tarReader); err != nil {
				outFile.Close()
				return "", fmt.Errorf("failed to write file: %w", err)
			}
			outFile.Close()
		}
	}

	// Validate the imported skill
	skillMdPath := filepath.Join(skillDir, "SKILL.md")
	content, err := os.ReadFile(skillMdPath)
	if err != nil {
		os.RemoveAll(skillDir) // Clean up on error
		return "", fmt.Errorf("failed to read SKILL.md: %w", err)
	}

	metadata, _, err := ParseFrontmatter(string(content))
	if err != nil {
		os.RemoveAll(skillDir) // Clean up on error
		return "", fmt.Errorf("failed to parse SKILL.md: %w", err)
	}

	// Validate that name in frontmatter matches directory name
	if metadata.Name != skillName {
		os.RemoveAll(skillDir) // Clean up on error
		return "", fmt.Errorf("skill name in frontmatter (%s) does not match directory name (%s)", metadata.Name, skillName)
	}

	return skillName, nil
}

// findSkillDirByName recursively finds a skill directory by name within a base path
func findSkillDirByName(basePath, targetName string) (string, error) {
	var foundPath string
	err := filepath.Walk(basePath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil // Skip errors, continue walking
		}
		if !info.IsDir() {
			return nil
		}
		// Check if this directory contains SKILL.md and matches the target name
		skillMdPath := filepath.Join(path, "SKILL.md")
		if _, err := os.Stat(skillMdPath); err == nil {
			dirName := filepath.Base(path)
			if dirName == targetName {
				foundPath = path
				return filepath.SkipAll // Found it, stop walking
			}
		}
		return nil
	})
	if err != nil {
		return "", err
	}
	if foundPath == "" {
		return "", fmt.Errorf("skill directory not found: %s", targetName)
	}
	return foundPath, nil
}

package domain

import (
	"encoding/base64"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// SkillManager defines the interface for managing skills
type SkillManager interface {
	ListSkills() ([]Skill, error)
	ReadSkill(name string) (*Skill, error)
	SearchSkills(query string) ([]Skill, error)
	RebuildIndex() error

	// Resource management methods
	ListSkillResources(skillID string) ([]SkillResource, error)
	ReadSkillResource(skillID, resourcePath string) (*ResourceContent, error)
	GetSkillResourceInfo(skillID, resourcePath string) (*SkillResource, error)
}

// FileSystemManager implements SkillManager using the file system
type FileSystemManager struct {
	skillsDir string
	searcher  *Searcher
	gitRepos  []string // List of git repo directory names (for read-only detection)
}

// NewFileSystemManager creates a new FileSystemManager
func NewFileSystemManager(skillsDir string, gitRepos []string) (*FileSystemManager, error) {
	if err := os.MkdirAll(skillsDir, 0755); err != nil {
		return nil, fmt.Errorf("failed to create skills directory: %w", err)
	}

	searcher, err := NewSearcher(skillsDir)
	if err != nil {
		return nil, fmt.Errorf("failed to create searcher: %w", err)
	}

	manager := &FileSystemManager{
		skillsDir: skillsDir,
		searcher:  searcher,
		gitRepos:  gitRepos,
	}

	// Initial index build
	if err := manager.RebuildIndex(); err != nil {
		return nil, fmt.Errorf("failed to build initial index: %w", err)
	}

	return manager, nil
}

// isGitRepoPath checks if a path is within a git repository directory
func (m *FileSystemManager) isGitRepoPath(path string) bool {
	relPath, err := filepath.Rel(m.skillsDir, path)
	if err != nil {
		return false
	}

	// Check if path starts with any git repo name
	parts := strings.Split(relPath, string(filepath.Separator))
	if len(parts) > 0 {
		for _, repoName := range m.gitRepos {
			if parts[0] == repoName {
				return true
			}
		}
	}
	return false
}

// isKnownRepoDir checks if a directory name corresponds to a cloned git repo
// (i.e., has a .git subdirectory) but is not in the enabled repos list.
// This prevents disabled repo root-level skills from appearing as local skills.
func (m *FileSystemManager) isKnownRepoDir(dirName string) bool {
	gitDir := filepath.Join(m.skillsDir, dirName, ".git")
	info, err := os.Stat(gitDir)
	return err == nil && info.IsDir()
}

// findSkillDirs recursively finds all directories containing SKILL.md files
func (m *FileSystemManager) findSkillDirs(root string, basePath string) ([]string, error) {
	var skillDirs []string

	entries, err := os.ReadDir(root)
	if err != nil {
		return nil, err
	}

	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}

		entryPath := filepath.Join(root, entry.Name())

		// Check if this directory contains SKILL.md
		skillMdPath := filepath.Join(entryPath, "SKILL.md")
		if _, err := os.Stat(skillMdPath); err == nil {
			// Found a skill directory
			relPath, _ := filepath.Rel(basePath, entryPath)
			skillDirs = append(skillDirs, relPath)
		}

		// Recursively search subdirectories (for git repos)
		subDirs, err := m.findSkillDirs(entryPath, basePath)
		if err == nil {
			skillDirs = append(skillDirs, subDirs...)
		}
	}

	return skillDirs, nil
}

// ListSkills returns all skills (local and from git repos)
func (m *FileSystemManager) ListSkills() ([]Skill, error) {
	var skills []Skill

	// Find all directories containing SKILL.md
	skillDirs, err := m.findSkillDirs(m.skillsDir, m.skillsDir)
	if err != nil {
		return nil, fmt.Errorf("failed to find skill directories: %w", err)
	}

	for _, skillDir := range skillDirs {
		// Determine skill name and read-only status
		skillPath := filepath.Join(m.skillsDir, skillDir)

		// Check if this is from a git repo by checking if the path starts with a repo name
		relPath, err := filepath.Rel(m.skillsDir, skillPath)
		if err != nil {
			continue
		}
		parts := strings.Split(relPath, string(filepath.Separator))

		// Check if this skill is from a git repo (first part of path matches a repo name)
		repoName := parts[0]
		isFromRepo := false
		for _, enabledRepoName := range m.gitRepos {
			if enabledRepoName == repoName {
				isFromRepo = true
				break
			}
		}
		// For paths within repo directories (both root-level and nested), skip if repo is disabled
		if len(parts) > 1 && !isFromRepo {
			continue
		}
		// For single-part paths, skip if it matches a known (but disabled) repo directory
		if len(parts) == 1 && !isFromRepo && m.isKnownRepoDir(repoName) {
			continue
		}

		isReadOnly := m.isGitRepoPath(skillPath)

		var skillName string
		if isReadOnly {
			// For git repo skills, use repoName/directoryName format
			if len(parts) >= 2 {
				// Extract repo name and skill directory name
				repoName := parts[0]
				skillDirName := parts[len(parts)-1]
				skillName = fmt.Sprintf("%s/%s", repoName, skillDirName)
			} else {
				skillName = skillDir
			}
		} else {
			// For local skills, use directory name
			skillName = filepath.Base(skillDir)
		}

		skill, err := m.readSkillFromPath(skillPath, skillName, isReadOnly)
		if err != nil {
			// Skip skills that can't be read
			continue
		}
		skills = append(skills, *skill)
	}

	return skills, nil
}

// readSkillFromPath reads a skill from a directory path
func (m *FileSystemManager) readSkillFromPath(skillPath, skillName string, isReadOnly bool) (*Skill, error) {
	skillMdPath := filepath.Join(skillPath, "SKILL.md")
	content, err := os.ReadFile(skillMdPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read SKILL.md: %w", err)
	}

	metadata, contentStr, err := ParseFrontmatter(string(content))
	if err != nil {
		return nil, fmt.Errorf("failed to parse frontmatter: %w", err)
	}

	// Validate that name in frontmatter matches directory name
	dirName := filepath.Base(skillPath)
	if metadata.Name != dirName {
		return nil, fmt.Errorf("skill name in frontmatter (%s) does not match directory name (%s)", metadata.Name, dirName)
	}

	return &Skill{
		Name:       skillName,
		ID:         skillName, // ID is the same as Name - the identifier to use when reading
		Content:    contentStr,
		Metadata:   metadata,
		SourcePath: skillPath,
		ReadOnly:   isReadOnly,
	}, nil
}

// findSkillDirByName recursively finds a skill directory by name within a base path
func (m *FileSystemManager) findSkillDirByName(basePath, targetName string) (string, error) {
	var foundPath string
	err := filepath.Walk(basePath, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil // Skip errors, continue walking
		}
		if !info.IsDir() {
			return nil
		}
		// Check if this directory contains SKILL.md and matches the target name
		skillMdPath := filepath.Join(path, "SKILL.md")
		if _, err := os.Stat(skillMdPath); err == nil {
			dirName := filepath.Base(path)
			if dirName == targetName {
				foundPath = path
				return filepath.SkipAll // Found it, stop walking
			}
		}
		return nil
	})
	if err != nil {
		return "", err
	}
	if foundPath == "" {
		return "", fmt.Errorf("skill directory not found: %s", targetName)
	}
	return foundPath, nil
}

// ReadSkill reads a skill by name (supports both local skills and git repo skills with repoName/skillName format)
func (m *FileSystemManager) ReadSkill(name string) (*Skill, error) {
	// Check if this is a git repo skill (format: repoName/skillName)
	if strings.Contains(name, "/") {
		parts := strings.Split(name, "/")
		if len(parts) == 2 {
			repoName := parts[0]
			skillDirName := parts[1]
			repoPath := filepath.Join(m.skillsDir, repoName)

			// Check if repo directory exists
			if _, err := os.Stat(repoPath); err != nil {
				return nil, fmt.Errorf("skill not found: %s", name)
			}

			// Recursively search for the skill directory within the repo
			skillPath, err := m.findSkillDirByName(repoPath, skillDirName)
			if err != nil {
				return nil, fmt.Errorf("skill not found: %s", name)
			}

			return m.readSkillFromPath(skillPath, name, true)
		}
	}

	// Local skill or root-level repo skill - look for directory with this name
	skillPath := filepath.Join(m.skillsDir, name)
	skillMdPath := filepath.Join(skillPath, "SKILL.md")

	if _, err := os.Stat(skillMdPath); err != nil {
		return nil, fmt.Errorf("skill not found: %s", name)
	}

	isReadOnly := m.isGitRepoPath(skillPath)
	return m.readSkillFromPath(skillPath, name, isReadOnly)
}

// SearchSkills searches for skills matching the query
func (m *FileSystemManager) SearchSkills(query string) ([]Skill, error) {
	results, err := m.searcher.Search(query)
	if err != nil {
		return nil, err
	}

	// Read full skill content for each result
	var skills []Skill
	for _, result := range results {
		skill, err := m.ReadSkill(result.Name)
		if err != nil {
			// Skip skills that can't be read
			continue
		}
		skills = append(skills, *skill)
	}

	return skills, nil
}

// RebuildIndex rebuilds the search index
func (m *FileSystemManager) RebuildIndex() error {
	skills, err := m.ListSkills()
	if err != nil {
		return err
	}

	return m.searcher.IndexSkills(skills)
}

// GetSkillsDir returns the skills directory path
func (m *FileSystemManager) GetSkillsDir() string {
	return m.skillsDir
}

// UpdateGitRepos updates the list of git repository names for read-only detection
func (m *FileSystemManager) UpdateGitRepos(gitRepoNames []string) {
	m.gitRepos = gitRepoNames
}

// getSkillPath returns the full path to a skill directory given its ID
func (m *FileSystemManager) getSkillPath(skillID string) (string, error) {
	// Check if this is a git repo skill (format: repoName/skillName)
	if strings.Contains(skillID, "/") {
		parts := strings.Split(skillID, "/")
		if len(parts) == 2 {
			repoName := parts[0]
			skillDirName := parts[1]
			repoPath := filepath.Join(m.skillsDir, repoName)

			// Recursively search for the skill directory within the repo
			skillPath, err := m.findSkillDirByName(repoPath, skillDirName)
			if err != nil {
				return "", fmt.Errorf("skill not found: %s", skillID)
			}
			return skillPath, nil
		}
	}

	// Local skill
	skillPath := filepath.Join(m.skillsDir, skillID)
	skillMdPath := filepath.Join(skillPath, "SKILL.md")
	if _, err := os.Stat(skillMdPath); err != nil {
		return "", fmt.Errorf("skill not found: %s", skillID)
	}
	return skillPath, nil
}

// ListSkillResources lists all resources in a skill's optional directories
func (m *FileSystemManager) ListSkillResources(skillID string) ([]SkillResource, error) {
	skillPath, err := m.getSkillPath(skillID)
	if err != nil {
		return nil, err
	}

	var resources []SkillResource
	resourceDirs := []string{"scripts", "references", "assets"}

	for _, dir := range resourceDirs {
		dirPath := filepath.Join(skillPath, dir)
		entries, err := os.ReadDir(dirPath)
		if err != nil {
			// Directory doesn't exist, skip
			continue
		}

		for _, entry := range entries {
			if entry.IsDir() {
				// Recursively list subdirectories
				subResources, err := m.listResourcesInDir(skillPath, filepath.Join(dir, entry.Name()))
				if err == nil {
					resources = append(resources, subResources...)
				}
				continue
			}

			resourcePath := filepath.Join(dir, entry.Name())
			fullPath := filepath.Join(skillPath, resourcePath)

			info, err := entry.Info()
			if err != nil {
				continue
			}

			// Read file to detect MIME type
			content, err := os.ReadFile(fullPath)
			if err != nil {
				continue
			}

			mimeType := DetectMimeType(entry.Name(), content)
			readable := IsTextFile(mimeType)

			resources = append(resources, SkillResource{
				Type:     GetResourceType(resourcePath),
				Path:     filepath.ToSlash(resourcePath), // Use forward slashes for consistency
				Name:     entry.Name(),
				Size:     info.Size(),
				MimeType: mimeType,
				Readable: readable,
				Modified: info.ModTime(),
			})
		}
	}

	return resources, nil
}

// listResourcesInDir recursively lists resources in a subdirectory
func (m *FileSystemManager) listResourcesInDir(skillPath, relPath string) ([]SkillResource, error) {
	var resources []SkillResource
	fullPath := filepath.Join(skillPath, relPath)

	entries, err := os.ReadDir(fullPath)
	if err != nil {
		return nil, err
	}

	for _, entry := range entries {
		if entry.IsDir() {
			// Recursively list subdirectories
			subResources, err := m.listResourcesInDir(skillPath, filepath.Join(relPath, entry.Name()))
			if err == nil {
				resources = append(resources, subResources...)
			}
			continue
		}

		resourcePath := filepath.Join(relPath, entry.Name())
		fullResourcePath := filepath.Join(skillPath, resourcePath)

		info, err := entry.Info()
		if err != nil {
			continue
		}

		// Read file to detect MIME type
		content, err := os.ReadFile(fullResourcePath)
		if err != nil {
			continue
		}

		mimeType := DetectMimeType(entry.Name(), content)
		readable := IsTextFile(mimeType)

		resources = append(resources, SkillResource{
			Type:     GetResourceType(resourcePath),
			Path:     filepath.ToSlash(resourcePath),
			Name:     entry.Name(),
			Size:     info.Size(),
			MimeType: mimeType,
			Readable: readable,
			Modified: info.ModTime(),
		})
	}

	return resources, nil
}

// ReadSkillResource reads the content of a skill resource file
func (m *FileSystemManager) ReadSkillResource(skillID, resourcePath string) (*ResourceContent, error) {
	// Validate path
	if err := ValidateResourcePath(resourcePath); err != nil {
		return nil, err
	}

	skillPath, err := m.getSkillPath(skillID)
	if err != nil {
		return nil, err
	}

	fullPath := filepath.Join(skillPath, resourcePath)
	content, err := os.ReadFile(fullPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read resource: %w", err)
	}

	mimeType := DetectMimeType(filepath.Base(resourcePath), content)
	readable := IsTextFile(mimeType)

	var encoding string
	var contentStr string

	if readable {
		// Try to decode as UTF-8
		contentStr = string(content)
		encoding = "utf-8"
	} else {
		// Encode as base64 for binary files
		contentStr = base64.StdEncoding.EncodeToString(content)
		encoding = "base64"
	}

	return &ResourceContent{
		Content:  contentStr,
		Encoding: encoding,
		MimeType: mimeType,
		Size:     int64(len(content)),
	}, nil
}

// GetSkillResourceInfo gets metadata about a specific resource without reading content
func (m *FileSystemManager) GetSkillResourceInfo(skillID, resourcePath string) (*SkillResource, error) {
	// Validate path
	if err := ValidateResourcePath(resourcePath); err != nil {
		return nil, err
	}

	skillPath, err := m.getSkillPath(skillID)
	if err != nil {
		return nil, err
	}

	fullPath := filepath.Join(skillPath, resourcePath)
	info, err := os.Stat(fullPath)
	if err != nil {
		return nil, fmt.Errorf("resource not found: %w", err)
	}

	if info.IsDir() {
		return nil, fmt.Errorf("resource path points to a directory, not a file")
	}

	// Read a small portion to detect MIME type
	file, err := os.Open(fullPath)
	if err != nil {
		return nil, fmt.Errorf("failed to open resource: %w", err)
	}
	defer file.Close()

	buffer := make([]byte, 512)
	n, _ := file.Read(buffer)
	mimeType := DetectMimeType(filepath.Base(resourcePath), buffer[:n])
	readable := IsTextFile(mimeType)

	return &SkillResource{
		Type:     GetResourceType(resourcePath),
		Path:     filepath.ToSlash(resourcePath),
		Name:     filepath.Base(resourcePath),
		Size:     info.Size(),
		MimeType: mimeType,
		Readable: readable,
		Modified: info.ModTime(),
	}, nil
}

package web

import (
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/labstack/echo/v5"

	"github.com/mudler/skillserver/pkg/domain"
	"github.com/mudler/skillserver/pkg/git"
)

// SkillResponse represents a skill in API responses
type SkillResponse struct {
	Name          string            `json:"name"`
	Content       string            `json:"content"`
	Description   string            `json:"description,omitempty"`
	License       string            `json:"license,omitempty"`
	Compatibility string            `json:"compatibility,omitempty"`
	Metadata      map[string]string `json:"metadata,omitempty"`
	AllowedTools  string            `json:"allowed-tools,omitempty"`
	ReadOnly      bool              `json:"readOnly"`
}

// CreateSkillRequest represents a request to create a skill
type CreateSkillRequest struct {
	Name          string            `json:"name"`
	Description   string            `json:"description"`
	Content       string            `json:"content"`
	License       string            `json:"license,omitempty"`
	Compatibility string            `json:"compatibility,omitempty"`
	Metadata      map[string]string `json:"metadata,omitempty"`
	AllowedTools  string            `json:"allowed-tools,omitempty"`
}

// UpdateSkillRequest represents a request to update a skill
type UpdateSkillRequest struct {
	Description   string            `json:"description"`
	Content       string            `json:"content"`
	License       string            `json:"license,omitempty"`
	Compatibility string            `json:"compatibility,omitempty"`
	Metadata      map[string]string `json:"metadata,omitempty"`
	AllowedTools  string            `json:"allowed-tools,omitempty"`
}

// listSkills lists all skills
func (s *Server) listSkills(c *echo.Context) error {
	skills, err := s.skillManager.ListSkills()
	if err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": err.Error(),
		})
	}

	responses := make([]SkillResponse, len(skills))
	for i, skill := range skills {
		responses[i] = SkillResponse{
			Name:     skill.Name,
			Content:  skill.Content,
			ReadOnly: skill.ReadOnly,
		}
		if skill.Metadata != nil {
			responses[i].Description = skill.Metadata.Description
			responses[i].License = skill.Metadata.License
			responses[i].Compatibility = skill.Metadata.Compatibility
			responses[i].Metadata = skill.Metadata.Metadata
			responses[i].AllowedTools = skill.Metadata.AllowedTools.String()
		}
	}

	return c.JSON(http.StatusOK, responses)
}

// getSkill gets a single skill by name
func (s *Server) getSkill(c *echo.Context) error {
	name := c.Param("name")
	skill, err := s.skillManager.ReadSkill(name)
	if err != nil {
		return c.JSON(http.StatusNotFound, map[string]string{
			"error": "skill not found",
		})
	}

	response := SkillResponse{
		Name:     skill.Name,
		Content:  skill.Content,
		ReadOnly: skill.ReadOnly,
	}
	if skill.Metadata != nil {
		response.Description = skill.Metadata.Description
		response.License = skill.Metadata.License
		response.Compatibility = skill.Metadata.Compatibility
		response.Metadata = skill.Metadata.Metadata
		response.AllowedTools = skill.Metadata.AllowedTools.String()
	}

	return c.JSON(http.StatusOK, response)
}

// createSkill creates a new skill
func (s *Server) createSkill(c *echo.Context) error {
	var req CreateSkillRequest
	if err := c.Bind(&req); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "invalid request",
		})
	}

	// Validate name
	if req.Name == "" {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "name is required",
		})
	}

	// Validate name according to Agent Skills spec
	if err := domain.ValidateSkillName(req.Name); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": err.Error(),
		})
	}

	// Validate description
	if req.Description == "" {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "description is required",
		})
	}
	if len(req.Description) > 1024 {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "description must be 1-1024 characters",
		})
	}

	// Validate compatibility if provided
	if req.Compatibility != "" && len(req.Compatibility) > 500 {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "compatibility must be max 500 characters",
		})
	}

	// Get the skills directory from the manager
	fsManager, ok := s.skillManager.(*domain.FileSystemManager)
	if !ok {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "unsupported manager type",
		})
	}

	// Create skill directory
	skillsDir := fsManager.GetSkillsDir()
	skillDir := filepath.Join(skillsDir, req.Name)
	if err := os.MkdirAll(skillDir, 0755); err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": fmt.Sprintf("failed to create skill directory: %v", err),
		})
	}

	// Build frontmatter
	frontmatter := fmt.Sprintf("---\nname: %s\ndescription: %s\n", req.Name, req.Description)
	if req.License != "" {
		frontmatter += fmt.Sprintf("license: %s\n", req.License)
	}
	if req.Compatibility != "" {
		frontmatter += fmt.Sprintf("compatibility: %s\n", req.Compatibility)
	}
	if len(req.Metadata) > 0 {
		frontmatter += "metadata:\n"
		for k, v := range req.Metadata {
			frontmatter += fmt.Sprintf("  %s: %s\n", k, v)
		}
	}
	if req.AllowedTools != "" {
		frontmatter += fmt.Sprintf("allowed-tools: %s\n", req.AllowedTools)
	}
	frontmatter += "---\n\n"

	// Write SKILL.md file
	skillMdPath := filepath.Join(skillDir, "SKILL.md")
	fullContent := frontmatter + req.Content
	if err := writeFile(skillMdPath, fullContent); err != nil {
		os.RemoveAll(skillDir) // Clean up on error
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": err.Error(),
		})
	}

	// Rebuild index
	if err := s.skillManager.RebuildIndex(); err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to rebuild index",
		})
	}

	skill, err := s.skillManager.ReadSkill(req.Name)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to read created skill",
		})
	}

	response := SkillResponse{
		Name:     skill.Name,
		Content:  skill.Content,
		ReadOnly: skill.ReadOnly,
	}
	if skill.Metadata != nil {
		response.Description = skill.Metadata.Description
		response.License = skill.Metadata.License
		response.Compatibility = skill.Metadata.Compatibility
		response.Metadata = skill.Metadata.Metadata
		response.AllowedTools = skill.Metadata.AllowedTools.String()
	}

	return c.JSON(http.StatusCreated, response)
}

// updateSkill updates an existing skill
func (s *Server) updateSkill(c *echo.Context) error {
	name := c.Param("name")

	// Check if skill exists and is read-only
	existingSkill, err := s.skillManager.ReadSkill(name)
	if err != nil {
		return c.JSON(http.StatusNotFound, map[string]string{
			"error": "skill not found",
		})
	}
	if existingSkill.ReadOnly {
		return c.JSON(http.StatusForbidden, map[string]string{
			"error": "cannot update read-only skill from git repository",
		})
	}

	var req UpdateSkillRequest
	if err := c.Bind(&req); err != nil {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "invalid request",
		})
	}

	// Validate description
	if req.Description == "" {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "description is required",
		})
	}
	if len(req.Description) > 1024 {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "description must be 1-1024 characters",
		})
	}

	// Validate compatibility if provided
	if req.Compatibility != "" && len(req.Compatibility) > 500 {
		return c.JSON(http.StatusBadRequest, map[string]string{
			"error": "compatibility must be max 500 characters",
		})
	}

	// Get the skills directory from the manager
	fsManager, ok := s.skillManager.(*domain.FileSystemManager)
	if !ok {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "unsupported manager type",
		})
	}

	// Build frontmatter (name must match directory name)
	skillDir := filepath.Join(fsManager.GetSkillsDir(), name)
	frontmatter := fmt.Sprintf("---\nname: %s\ndescription: %s\n", name, req.Description)
	if req.License != "" {
		frontmatter += fmt.Sprintf("license: %s\n", req.License)
	}
	if req.Compatibility != "" {
		frontmatter += fmt.Sprintf("compatibility: %s\n", req.Compatibility)
	}
	if len(req.Metadata) > 0 {
		frontmatter += "metadata:\n"
		for k, v := range req.Metadata {
			frontmatter += fmt.Sprintf("  %s: %s\n", k, v)
		}
	}
	if req.AllowedTools != "" {
		frontmatter += fmt.Sprintf("allowed-tools: %s\n", req.AllowedTools)
	}
	frontmatter += "---\n\n"

	// Write SKILL.md file
	skillMdPath := filepath.Join(skillDir, "SKILL.md")
	fullContent := frontmatter + req.Content
	if err := writeFile(skillMdPath, fullContent); err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": err.Error(),
		})
	}

	// Rebuild index
	if err := s.skillManager.RebuildIndex(); err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to rebuild index",
		})
	}

	skill, err := s.skillManager.ReadSkill(name)
	if err != nil {
		return c.JSON(http.StatusInternalServerError, map[string]string{
			"error": "failed to read updated skill",
		})
	}

	response := SkillResponse{
		Name:     skill.Name,
		Content:  skill.Content,
		ReadOnly: skill.ReadOnly,
	}
	if skill.Metadata != nil {
		response.Description = skill.Metadata.Description
		response.License = skill.Metadata.License
		response.Compatibility = skill.Metadata.Compatibility
		response.Metadata = skill.Metadata.Metadata
		response.AllowedTools = skill.Metadata.AllowedTools.String()
	}

	return c.JSON(http.StatusOK, response)
}

